{
  "name": "opencode-beads",
  "version": "0.9.0",
  "type": "module",
  "description": "A plugin for OpenCode that provides integration with the beads issue tracker.",
  "author": "Josh Thomas <josh@joshthomas.dev>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/joshuadavidthomas/opencode-beads"
  },
  "keywords": [
    "opencode",
    "plugin",
    "beads",
    "agent",
    "ai"
  ],
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./server": "./dist/index.js"
  },
  "files": ["dist", "vendor", "README.md"],
  "scripts": {
    "build": "bun build ./index.ts --outdir ./dist --target node --format esm --packages external",
    "prepack": "bun run build",
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.1.2"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "@types/node": "^22.0.0",
    "typescript": "~5.9.3"
  },
  "engines": {
    "bun": ">=1.0.0"
  }
}
